// One dated row per keyword: AI Overview shown, site cited and rank, brand named, cited domains, organic position.
const today = new Date().toISOString().slice(0, 10);
return $input.all()
  .map((i) => i.json)
  .filter((r) => r.found !== false)
  .map((r) => ({
    json: {
      week: today,
      keyword: r.keyword,
      aiOverviewShown: r.aiOverviewPresent,
      citedInAiOverview: r.domainCitedInAiOverview,
      citationRank: r.citationRank,
      citedUrl: r.citedUrl,
      brandNamed: r.brandMentionedInAiOverview,
      topCitedDomains: (r.citedDomains ?? []).slice(0, 5).join(', '),
      organicPosition: r.organicPosition,
      country: r.country,
    },
  }));
